package org.apache.commons.cli2.commandline;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Properties;
import java.util.Set;
import org.apache.commons.cli2.Argument;
import org.apache.commons.cli2.Option;
import org.apache.commons.cli2.WriteableCommandLine;
import org.apache.commons.cli2.commandline.WriteableCommandLineImpl;
import org.apache.commons.cli2.option.PropertyOption;
import org.apache.commons.cli2.resource.ResourceConstants;
import org.apache.commons.cli2.resource.ResourceHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class WriteableCommandLineImpl_getValues_TriageGen1Test {

    @Test
    public void test_getValues_nullOption() {
        WriteableCommandLineImpl impl = new WriteableCommandLineImpl(null, new ArrayList<>());
        try {
            impl.getValues(null, new ArrayList<>());
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {}
    }

    @Test
    public void test_getValues_nullDefaultValues() {
        WriteableCommandLineImpl impl = new WriteableCommandLineImpl(new Option(), new ArrayList<>());
        try {
            impl.getValues(new Option(), null);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {}
    }

    @Test
    public void test_getValues_optionNotAdded() {
        WriteableCommandLineImpl impl = new WriteableCommandLineImpl(new Option(), new ArrayList<>());
        impl.getValues(new Option(), new ArrayList<>());
        assertTrue(impl.getValues(new Option(), new ArrayList<>()).isEmpty());
    }

    @Test
    public void test_getValues_defaultValuesEmpty() {
        WriteableCommandLineImpl impl = new WriteableCommandLineImpl(new Option(), new ArrayList<>());
        List defaultValues = new ArrayList<>();
        assertTrue(impl.getValues(new Option(), defaultValues).isEmpty());
    }

    @Test
    public void test_getValues_defaultValuesNotEmpty() {
        WriteableCommandLineImpl impl = new WriteableCommandLineImpl(new Option(), new ArrayList<>());
        List defaultValues = new ArrayList<>();
        defaultValues.add("value1");
        defaultValues.add("value2");
        List values = impl.getValues(new Option(), defaultValues);
        assertEquals(2, values.size());
        assertEquals("value1", values.get(0));
        assertEquals("value2", values.get(1));
    }

    @Test
    public void test_getValues_optionAdded() {
        WriteableCommandLineImpl impl = new WriteableCommandLineImpl(new Option(), new ArrayList<>());
        impl.addValue(new Option(), "value1");
        impl.addValue(new Option(), "value2");
        List values = impl.getValues(new Option(), new ArrayList<>());
        assertEquals(2, values.size());
        assertEquals("value1", values.get(0));
        assertEquals("value2", values.get(1));
    }

    @Test
    public void test_getValues_bothDefaultAndSpecifiedValues() {
        WriteableCommandLineImpl impl = new WriteableCommandLineImpl(new Option(), new ArrayList<>());
        List defaultValues = new ArrayList<>();
        defaultValues.add("defaultValue1");
        impl.setDefaultValues(new Option(), defaultValues);
        List values = impl.getValues(new Option(), new ArrayList<>());
        assertEquals(1, values.size());
        assertEquals("defaultValue1", values.get(0));
    }

    @Test
    public void test_getValues_bothDefaultAndSpecifiedValuesNotEmpty() {
        WriteableCommandLineImpl impl = new WriteableCommandLineImpl(new Option(), new ArrayList<>());
        List defaultValues = new ArrayList<>();
        defaultValues.add("defaultValue1");
        defaultValues.add("defaultValue2");
        impl.setDefaultValues(new Option(), defaultValues);
        List values = impl.getValues(new Option(), new ArrayList<>());
        assertEquals(2, values.size());
        assertEquals("defaultValue1", values.get(0));
        assertEquals("defaultValue2", values.get(1));
    }

    @Test
    public void test_getValues_valueListNull() {
        WriteableCommandLineImpl impl = new WriteableCommandLineImpl(new Option(), new ArrayList<>());
        impl.getValues(new Option(), new ArrayList<>());
        List valueList = impl.getValues(new Option(), new ArrayList<>());
        assertTrue(valueList == null);
    }
}
